def samples(known):
 out=[];seen=set(known)
 styles=[lambda s:s,lambda s:'رها '+s,lambda s:s+' لطفا',lambda s:'لطفا '+s,lambda s:'خب '+s,lambda s:s+' الان']
 for i,f in enumerate(families()):
  chosen=[]
  for style in styles:
   for core in f['phrases']:
    t=normalize(style(core))
    if t in seen:continue
    seen.add(t);chosen.append(dict(text=t,action=f['action'],parameters=f['parameters'],alternatives=f['alternatives'],policy=f['policy'],family=f'scenario-{i+1:02}',core=normalize(core)))
    if len(chosen)==20:break
   if len(chosen)==20:break
  assert len(chosen)==20,(i,len(chosen))
  out.extend(chosen)
 assert len(out)==1000
 return out
